BEGIN;
CREATE TABLE app.customer_invoice_sequence(id uuid NOT NULL,tenant_id uuid NOT NULL,next_number bigint NOT NULL DEFAULT 1 CHECK(next_number>0),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id));
CREATE TABLE app.customer_invoice(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,final_account_revision_id uuid NOT NULL,authorization_id uuid NOT NULL,invoice_number varchar(32) NOT NULL,issued_on date NOT NULL,issuer_details jsonb NOT NULL,tax_policy_version varchar(80) NOT NULL CHECK(tax_policy_version='candidate_m1_standard_v1'),currency char(3) NOT NULL CHECK(currency='GBP'),net_pence bigint NOT NULL,tax_pence bigint NOT NULL,total_pence bigint NOT NULL CHECK(total_pence=net_pence+tax_pence),source_hash char(64) NOT NULL,pdf_sha256 char(64) NOT NULL,pdf_bytes bytea NOT NULL,synthetic boolean NOT NULL CHECK(synthetic),watermark varchar(80) NOT NULL CHECK(watermark='SYNTHETIC - NOT A REAL INVOICE'),created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,invoice_number),UNIQUE(tenant_id,final_account_revision_id),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,final_account_revision_id) REFERENCES app.final_account_revision(tenant_id,job_id,id),FOREIGN KEY(tenant_id,authorization_id) REFERENCES app.action_authorization(tenant_id,id));
CREATE TABLE app.customer_invoice_evidence(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,invoice_id uuid NOT NULL,evidence_id uuid NOT NULL,object_version_id varchar(1024) NOT NULL,sha256 char(64) NOT NULL,scope_item_id uuid NOT NULL,PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,invoice_id,evidence_id),FOREIGN KEY(tenant_id,job_id,invoice_id) REFERENCES app.customer_invoice(tenant_id,job_id,id),FOREIGN KEY(tenant_id,evidence_id) REFERENCES app.evidence_object(tenant_id,id));
CREATE TABLE app.customer_credit_note(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,invoice_id uuid NOT NULL,authorization_id uuid NOT NULL,credit_number varchar(40) NOT NULL,amount_pence bigint NOT NULL CHECK(amount_pence>0),currency char(3) NOT NULL CHECK(currency='GBP'),reason varchar(240) NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,credit_number),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,invoice_id) REFERENCES app.customer_invoice(tenant_id,job_id,id),FOREIGN KEY(tenant_id,authorization_id) REFERENCES app.action_authorization(tenant_id,id));
CREATE TABLE app.customer_payment(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,invoice_id uuid NOT NULL,authorization_id uuid NOT NULL,paid_on date NOT NULL,amount_pence bigint NOT NULL CHECK(amount_pence>0),currency char(3) NOT NULL CHECK(currency='GBP'),method varchar(24) NOT NULL CHECK(method IN('bank_transfer','cash','card_elsewhere','cheque','other')),reference varchar(120) NOT NULL,builder_attested boolean NOT NULL CHECK(builder_attested),provenance varchar(32) NOT NULL CHECK(provenance='manual_builder_attestation'),qualifying_recovery_proof boolean NOT NULL DEFAULT false CHECK(NOT qualifying_recovery_proof),platform_fee_settlement boolean NOT NULL DEFAULT false CHECK(NOT platform_fee_settlement),created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,job_id,id),FOREIGN KEY(tenant_id,job_id,invoice_id) REFERENCES app.customer_invoice(tenant_id,job_id,id),FOREIGN KEY(tenant_id,authorization_id) REFERENCES app.action_authorization(tenant_id,id));
CREATE TABLE app.customer_payment_reversal(id uuid NOT NULL,tenant_id uuid NOT NULL,job_id uuid NOT NULL,payment_id uuid NOT NULL,authorization_id uuid NOT NULL,reason varchar(240) NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,payment_id),FOREIGN KEY(tenant_id,job_id,payment_id) REFERENCES app.customer_payment(tenant_id,job_id,id),FOREIGN KEY(tenant_id,authorization_id) REFERENCES app.action_authorization(tenant_id,id));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['customer_invoice_sequence','customer_invoice','customer_invoice_evidence','customer_credit_note','customer_payment','customer_payment_reversal'] LOOP EXECUTE format('ALTER TABLE app.%I OWNER TO jobguard_migration',t);EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE app.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON app.%I FOR ALL TO jobguard_runtime,jobguard_migration USING (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK (tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',t);EXECUTE format('GRANT SELECT,INSERT ON app.%I TO jobguard_runtime',t);EXECUTE format('REVOKE UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON app.%I FROM jobguard_runtime',t);END LOOP;END$$;
CREATE TRIGGER customer_invoice_immutable BEFORE UPDATE OR DELETE ON app.customer_invoice FOR EACH ROW EXECUTE FUNCTION app.reject_immutable_commercial_mutation();
CREATE TRIGGER customer_invoice_evidence_immutable BEFORE UPDATE OR DELETE ON app.customer_invoice_evidence FOR EACH ROW EXECUTE FUNCTION app.reject_immutable_commercial_mutation();
CREATE TRIGGER customer_credit_note_immutable BEFORE UPDATE OR DELETE ON app.customer_credit_note FOR EACH ROW EXECUTE FUNCTION app.reject_immutable_commercial_mutation();
CREATE TRIGGER customer_payment_immutable BEFORE UPDATE OR DELETE ON app.customer_payment FOR EACH ROW EXECUTE FUNCTION app.reject_immutable_commercial_mutation();
CREATE TRIGGER customer_payment_reversal_immutable BEFORE UPDATE OR DELETE ON app.customer_payment_reversal FOR EACH ROW EXECUTE FUNCTION app.reject_immutable_commercial_mutation();
CREATE FUNCTION app.reserve_customer_invoice_number(p_tenant uuid) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,app AS $$DECLARE n bigint;BEGIN IF p_tenant IS DISTINCT FROM nullif(current_setting('app.tenant_id',true),'')::uuid THEN RAISE EXCEPTION 'tenant context mismatch' USING ERRCODE='42501';END IF;INSERT INTO app.customer_invoice_sequence(id,tenant_id,next_number)VALUES(gen_random_uuid(),p_tenant,2) ON CONFLICT(tenant_id) DO UPDATE SET next_number=app.customer_invoice_sequence.next_number+1 RETURNING next_number-1 INTO n;RETURN n;END$$;
ALTER FUNCTION app.reserve_customer_invoice_number(uuid) OWNER TO jobguard_migration;GRANT EXECUTE ON FUNCTION app.reserve_customer_invoice_number(uuid) TO jobguard_runtime;
COMMIT;
